from collections import deque

def updateMatrix(mat):
    """Return matrix where each cell contains distance to nearest 0."""
    rows, cols = len(mat), len(mat[0])
    output = [[-1] * cols for _ in range(rows)]
    queue = deque()

    # Initialize queue with all 0 cells
    for r in range(rows):
        for c in range(cols):
            if mat[r][c] == 0:
                queue.append((r, c))
                output[r][c] = 0

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    # BFS traversal
    while queue:
        r, c = queue.popleft()
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and output[nr][nc] == -1:
                output[nr][nc] = output[r][c] + 1
                queue.append((nr, nc))

    return output
